import sys

def main():
    data = sys.stdin.read().split()
    if not data:
        return
    t = int(data[0])
    idx = 1
    out_lines = []
    for _ in range(t):
        # 读取26种彩珠的数量
        nums = list(map(int, data[idx:idx+26]))
        idx += 26
        total = sum(nums)
        max_cnt = max(nums)
        # 最长长度为 min(total, 2*(total - max_cnt) + 1)
        ans = min(total, 2 * (total - max_cnt) + 1)
        out_lines.append(str(ans))
    sys.stdout.write("\n".join(out_lines))

if __name__ == "__main__":
    main()
```

